 <body><main id="game"><canvas id="scene" aria-label="Aetherblade duel arena"></canvas><div class="vignette"></div>
 <div class="hud"><div><div class="topline"><div class="brand">Aetherblade <small>Steel &amp; Steam</small></div><div class="round">DUEL<strong>01 / 01</strong></div><button class="pause" id="pause" aria-label="Pause">Ⅱ</button></div><div class="bars"><div class="fighter-hud"><div class="name">THE WANDERER</div><div class="subname">IRON DISTRICT · DUELIST</div><div class="meter"><div class="fill" id="playerHealth"></div></div><div class="stamina"><div class="fill" id="playerStamina"></div></div></div><div class="centerstatus" id="status">READY</div><div class="fighter-hud enemy"><div class="name">THE WARDEN</div><div class="subname">CITY WATCH · VETERAN</div><div class="meter"><div class="fill" id="enemyHealth"></div></div><div class="stamina"><div class="fill" id="enemyStamina"></div></div></div></div></div>

input.newString:
function loop(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt);draw();requestAnimationFrame(loop)}
function togglePause(){if(!playing||ended)return;paused=!paused;ui.overlay.classList.toggle('hidden',!paused);if(paused){ui.overlay.querySelector('.eyebrow').textContent='DUEL PAUSED';ui.overlay.querySelector('h1').innerHTML='HOLD THE LINE<span>THE STREET CAN WAIT</span>';ui.overlay.querySelector('p').innerHTML='Catch your breath. The Warden will be waiting.';ui.start.textContent='Resume Duel'}else{ui.start.textContent='Enter the Duel';say('READY')}}
ui.start.addEventListener('click',()=>{if(paused){paused=false;ui.overlay.classList.add('hidden');return}reset()});ui.pause.addEventListener('click',togglePause);
ui.attack.addEventListener('pointerdown',e=>{e.preventDefault();ui.attack.classList.add('pressed');startAttack('p')});for(const id of ['guard','parry'])ui[id].addEventListener('pointerdown',e=>{e.preventDefault();ui[id].classList.add('pressed');id==='guard'?block(true):parry()});
function releaseGuard(){block(false);ui.guard.classList.remove('pressed')};ui.guard.addEventListener('pointerup',releaseGuard);ui.guard.addEventListener('pointercancel',releaseGuard);ui.guard.addEventListener('pointerleave',e=>{if(e.buttons===0)releaseGuard()});ui.parry.addEventListener('pointerup',()=>ui.parry.classList.remove('pressed'));ui.parry.addEventListener('pointercancel',()=>ui.parry.classList.remove('pressed'));ui.attack.addEventListener('pointerup',()=>ui.attack.classList.remove('pressed'));ui.attack.addEventListener('pointercancel',()=>ui.attack.classList.remove('pressed'));
document.querySelectorAll('[data-line]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.line;game.p.line=selected;document.querySelectorAll('[data-line]').forEach(x=>x.classList.toggle('active',x===b));say(selected.toUpperCase()+' LINE')}));
document.querySelectorAll('[data-move]').forEach(b=>{const val=Number(b.dataset.move);const down=e=>{e.preventDefault();keys[val<0?'TouchLeft':'TouchRight']=true;b.classList.add('active')};const up=()=>{keys[val<0?'TouchLeft':'TouchRight']=false;b.classList.remove('active')};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up)});
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyJ'||e.code==='Space')startAttack('p');if(e.code==='KeyK')block(true);if(e.code==='KeyL')parry();if(e.code==='KeyI')feint();if(e.code==='Digit1')document.querySelector('[data-line="high"]').click();if(e.code==='Digit2')document.querySelector('[data-line="mid"]').click();if(e.code==='Digit3')document.querySelector('[data-line="low"]').click();if(e.code==='Escape')togglePause()});window.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='KeyK')block(false)});
window.addEventListener('resize',resize);resize();game.p.line=selected;requestAnimationFrame(loop);
})();
</script></body></html>

